Component Testing & Custom Commands:
// Component test with Cypress
import ProductCard from './ProductCard.vue';

describe('ProductCard Component', () => {
  it('renders product info correctly', () => {
    cy.mount(ProductCard, {
      props: {
        product: {
          id: 1,
          name: 'Test Product',
          price: 29.99,
          image: '/test.jpg'
        }
      }
    });

    cy.contains('Test Product').should('be.visible');
    cy.contains('$29.99').should('be.visible');
    cy.get('img').should('have.attr', 'src', '/test.jpg');
  });

  it('emits add-to-cart event on button click', () => {
    const onAddToCart = cy.spy().as('addToCartSpy');

    cy.mount(ProductCard, {
      props: {
        product: { id: 1, name: 'Test', price: 10 },
        onAddToCart
      }
    });

    cy.contains('Add to Cart').click();
    cy.get('@addToCartSpy').should('have.been.calledWith', 1);
  });
});

// Custom commands
Cypress.Commands.add('login', (email, password) => {
  cy.session([email, password], () => {
    cy.visit('/login');
    cy.get('[data-cy=email]').type(email);
    cy.get('[data-cy=password]').type(password);
    cy.get('[data-cy=submit]').click();
    cy.url().should('not.include', '/login');
  });
});

Cypress.Commands.add('createFixture', (name, data) => {
  cy.writeFile(`cypress/fixtures/${name}.json`, data);
});

